}

pub fn summarize_panels(panels: &[Panel]) -> Vec<PanelSummary>;
```

Group panels by the exact `(width, height)` pair. Every occurrence is a separate copy, including repeated identical values. For each distinct pair, return its copy count and the sum of the areas of all copies. Calculate area in `u64` so multiplication does not overflow at `u32` dimensions.

Return summaries in ascending `(width, height)` order. An empty input returns an empty vector.

Do not include a `main` function. Do not use external packages, filesystem access, networking, clocks, or randomness.","reference_code":"use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Panel {
    pub width: u32,
    pub height: u32,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PanelSummary {
    pub width: u32,
    pub height: u32,
    pub copies: usize,
    pub combined_area: u64,
}

pub fn summarize_panels(panels: &[Panel]) -> Vec<PanelSummary> {
    let mut summaries: BTreeMap<(u32, u32), (usize, u64)> = BTreeMap::new();

    for panel in panels {
        let area = u64::from(panel.width) * u64::from(panel.height);
        let aggregate = summaries
            .entry((panel.width, panel.height))
            .or_insert((0, 0));
        aggregate.0 += 1;
        aggregate.1 += area;
    }

    summaries
        .into_iter()
        .map(|((width, height), (copies, combined_area))| PanelSummary {
            width,
            height,
            copies,
            combined_area,
        })
        .collect()
}
