mod solution;

use solution::{decode_readings, DecodeError, Reading};

fn frame(channel: u8, alarm: bool, value: i16) -> [u8; 4] {
    let header = 0x40 | (channel << 4) | if alarm { 0x08 } else { 0 };
    let [high, low] = value.to_be_bytes();
    [header, high, low, header ^ high ^ low ^ 0xA5]
}

#[test]
fn empty_input_decodes_to_empty_vector() {
    assert_eq!(decode_readings(&[]), Ok(Vec::<Reading>::new()));
}

#[test]
fn decodes_multiple_frames_in_input_order() {
    let mut input = Vec::new();
    input.extend_from_slice(&frame(2, true, -1234));
    input.extend_from_slice(&frame(0, false, 5678));
    input.extend_from_slice(&frame(3, false, -1));

    assert_eq!(
        decode_readings(&input),
        Ok(vec![
            Reading { channel: 2, alarm: true, value: -1234 },
            Reading { channel: 0, alarm: false, value: 5678 },
            Reading { channel: 3, alarm: false, value: -1 },
        ])
    );
}

#[test]
fn decodes_channel_and_signed_value_boundaries() {
    let mut input = Vec::new();
    input.extend_from_slice(&frame(0, false, i16::MIN));
    input.extend_from_slice(&frame(3, true, i16::MAX));
    input.extend_from_slice(&frame(1, true, 0));

    assert_eq!(
        decode_readings(&input),
        Ok(vec![
            Reading { channel: 0, alarm: false, value: i16::MIN },
            Reading { channel: 3, alarm: true, value: i16::MAX },
            Reading { channel: 1, alarm: true, value: 0 },
        ])
    );
}

#[test]
fn reports_each_possible_truncated_remainder_at_frame_start() {
    for remaining in 1..=3 {
        let input = vec![0u8; remaining];
        assert_eq!(
            decode_readings(&input),
            Err(DecodeError::TruncatedFrame { offset: 0, remaining })
        );
    }

    let mut after_valid = frame(1, false, 25).to_vec();
    after_valid.extend_from_slice(&[0x40, 0x12]);
    assert_eq!(
        decode_readings(&after_valid),
        Err(DecodeError::TruncatedFrame { offset: 4, remaining: 2 })
    );
}

#[test]
fn unsupported_version_is_checked_before_reserved_bits_and_checksum() {
    let input = [0x07, 0x12, 0x34, 0x00];

    assert_eq!(
        decode_readings(&input),
        Err(DecodeError::UnsupportedVersion { offset: 0, found: 0 })
    );

    let input_version_three = [0xC0, 0x00, 0x00, 0x00];
    assert_eq!(
        decode_readings(&input_version_three),
        Err(DecodeError::UnsupportedVersion { offset: 0, found: 3 })
    );
}

#[test]
fn reserved_bits_are_checked_before_checksum() {
    let input = [0x45, 0x12, 0x34, 0x00];

    assert_eq!(
        decode_readings(&input),
        Err(DecodeError::ReservedBitsSet { offset: 0, bits: 5 })
    );
}

#[test]
fn checksum_error_reports_calculated_expected_and_actual_bytes() {
    let header = 0x68;
    let high = 0xFE;
    let low = 0xDC;
    let expected = header ^ high ^ low ^ 0xA5;
    let actual = expected ^ 0xFF;
    let input = [header, high, low, actual];

    assert_eq!(
        decode_readings(&input),
        Err(DecodeError::ChecksumMismatch {
            offset: 0,
            expected,
            actual,
        })
    );
}

#[test]
fn errors_use_the_offset_of_the_first_invalid_frame() {
    let mut input = frame(0, false, 7).to_vec();
    input.extend_from_slice(&[0x42, 0x00, 0x00, 0x00]);
    input.extend_from_slice(&frame(3, true, 9));

    assert_eq!(
        decode_readings(&input),
        Err(DecodeError::ReservedBitsSet { offset: 4, bits: 2 })
    );
}
