mod solution;

use solution::{DecodeError, FeatureOptions};

fn checksum(mask: u8) -> u8 {
    mask.rotate_left(1) ^ 0xA7
}

#[test]
fn new_disables_both_options_and_encodes_canonically() {
    let options = FeatureOptions::new();
    assert_eq!(options.emulation, false);
    assert_eq!(options.extended_frames, false);
    assert_eq!(options.encode(), [0x00, 0xA7]);
}

#[test]
fn setters_change_only_the_named_option() {
    let mut options = FeatureOptions::new();

    options.set_emulation(true);
    assert_eq!(options, FeatureOptions { emulation: true, extended_frames: false });
    assert_eq!(options.encode(), [0x01, checksum(0x01)]);

    options.set_extended_frames(true);
    assert_eq!(options, FeatureOptions { emulation: true, extended_frames: true });
    assert_eq!(options.encode(), [0x03, checksum(0x03)]);

    options.set_emulation(false);
    assert_eq!(options, FeatureOptions { emulation: false, extended_frames: true });

    options.set_extended_frames(false);
    assert_eq!(options, FeatureOptions::new());
}

#[test]
fn all_valid_masks_round_trip() {
    let cases = [
        (0x00, false, false),
        (0x01, true, false),
        (0x02, false, true),
        (0x03, true, true),
    ];

    for (mask, emulation, extended_frames) in cases {
        let encoded = [mask, checksum(mask)];
        let decoded = FeatureOptions::decode(encoded).unwrap();
        assert_eq!(decoded, FeatureOptions { emulation, extended_frames });
        assert_eq!(decoded.encode(), encoded);
    }
}

#[test]
fn valid_mask_with_wrong_checksum_is_rejected() {
    assert_eq!(
        FeatureOptions::decode([0x03, checksum(0x03) ^ 0x01]),
        Err(DecodeError::ChecksumMismatch)
    );
}

#[test]
fn reserved_bits_take_precedence_over_checksum_validation() {
    for mask in [0x04u8, 0x80, 0xFF] {
        assert_eq!(
            FeatureOptions::decode([mask, checksum(mask)]),
            Err(DecodeError::ReservedBitsSet)
        );
        assert_eq!(
            FeatureOptions::decode([mask, checksum(mask) ^ 0x01]),
            Err(DecodeError::ReservedBitsSet)
        );
    }
}
