mod solution;

use solution::{encode_set_positions, BitChunk};

fn expected(positions: &[u64]) -> Vec<u8> {
    let mut bytes = Vec::new();
    bytes.extend_from_slice(&(positions.len() as u64).to_le_bytes());
    for position in positions {
        bytes.extend_from_slice(&position.to_le_bytes());
    }
    bytes
}

#[test]
fn empty_input_encodes_a_zero_u64_count() {
    assert_eq!(encode_set_positions(&[]), vec![0; 8]);
}

#[test]
fn chunks_with_no_set_bits_produce_no_positions() {
    let chunks = [
        BitChunk { base: 0, bits: 0 },
        BitChunk { base: u32::MAX, bits: 0 },
    ];
    assert_eq!(encode_set_positions(&chunks), vec![0; 8]);
}

#[test]
fn positions_are_sorted_and_overlapping_duplicates_are_preserved() {
    let chunks = [
        BitChunk { base: 10, bits: (1u16 << 0) | (1u16 << 3) },
        BitChunk { base: 0, bits: 1u16 << 15 },
        BitChunk { base: 8, bits: 1u16 << 2 },
    ];

    assert_eq!(encode_set_positions(&chunks), expected(&[10, 10, 13, 15]));
}

#[test]
fn every_bit_offset_uses_zero_as_the_least_significant_offset() {
    let chunks = [BitChunk { base: 100, bits: u16::MAX }];
    let positions: Vec<u64> = (100u64..=115u64).collect();
    assert_eq!(encode_set_positions(&chunks), expected(&positions));
}

#[test]
fn supports_the_maximum_base_without_overflow() {
    let chunks = [BitChunk {
        base: u32::MAX,
        bits: (1u16 << 0) | (1u16 << 15),
    }];
    assert_eq!(
        encode_set_positions(&chunks),
        expected(&[u64::from(u32::MAX), u64::from(u32::MAX) + 15])
    );
}

#[test]
fn encoding_does_not_mutate_or_reorder_the_input_slice() {
    let chunks = vec![
        BitChunk { base: 50, bits: 2 },
        BitChunk { base: 1, bits: 1 },
        BitChunk { base: 50, bits: 1 },
    ];
    let original = chunks.clone();

    let first = encode_set_positions(&chunks);
    let second = encode_set_positions(&chunks);

    assert_eq!(chunks, original);
    assert_eq!(first, expected(&[1, 50, 51]));
    assert_eq!(second, first);
}
