mod solution;

use solution::{DispatchReport, Dispatcher, Event, HandlerFlow};
use std::cell::RefCell;
use std::rc::Rc;

#[test]
fn dispatch_with_no_matching_handler_reports_nothing() {
    let mut dispatcher = Dispatcher::new();
    let report = dispatcher.dispatch(&Event { kind: 0, value: 17 });
    assert_eq!(report, DispatchReport { invoked: 0, stopped: false });
}

#[test]
fn matching_handlers_run_in_registration_order_and_receive_the_event() {
    let calls = Rc::new(RefCell::new(Vec::new()));
    let mut dispatcher = Dispatcher::new();

    for marker in [1, 2, 3] {
        let calls = Rc::clone(&calls);
        dispatcher.on(7, Box::new(move |event| {
            calls.borrow_mut().push((marker, event.kind, event.value));
            HandlerFlow::Continue
        }));
    }

    let report = dispatcher.dispatch(&Event { kind: 7, value: -42 });
    assert_eq!(report, DispatchReport { invoked: 3, stopped: false });
    assert_eq!(
        *calls.borrow(),
        vec![(1, 7, -42), (2, 7, -42), (3, 7, -42)]
    );
}

#[test]
fn stop_ends_only_the_current_dispatch_and_state_resets_next_time() {
    let calls = Rc::new(RefCell::new(Vec::new()));
    let mut dispatcher = Dispatcher::new();

    let first_calls = Rc::clone(&calls);
    dispatcher.on(4, Box::new(move |_| {
        first_calls.borrow_mut().push(1);
        HandlerFlow::Continue
    }));

    let stop_calls = Rc::clone(&calls);
    dispatcher.on(4, Box::new(move |_| {
        stop_calls.borrow_mut().push(2);
        HandlerFlow::Stop
    }));

    let skipped_calls = Rc::clone(&calls);
    dispatcher.on(4, Box::new(move |_| {
        skipped_calls.borrow_mut().push(3);
        HandlerFlow::Continue
    }));

    let event = Event { kind: 4, value: 0 };
    assert_eq!(
        dispatcher.dispatch(&event),
        DispatchReport { invoked: 2, stopped: true }
    );
    assert_eq!(
        dispatcher.dispatch(&event),
        DispatchReport { invoked: 2, stopped: true }
    );
    assert_eq!(*calls.borrow(), vec![1, 2, 1, 2]);
}

#[test]
fn handlers_are_isolated_by_kind_including_boundary_keys() {
    let calls = Rc::new(RefCell::new(Vec::new()));
    let mut dispatcher = Dispatcher::new();

    let low_calls = Rc::clone(&calls);
    dispatcher.on(0, Box::new(move |_| {
        low_calls.borrow_mut().push(0);
        HandlerFlow::Continue
    }));

    let high_calls = Rc::clone(&calls);
    dispatcher.on(u8::MAX, Box::new(move |_| {
        high_calls.borrow_mut().push(u8::MAX);
        HandlerFlow::Continue
    }));

    assert_eq!(
        dispatcher.dispatch(&Event { kind: u8::MAX, value: i32::MAX }),
        DispatchReport { invoked: 1, stopped: false }
    );
    assert_eq!(
        dispatcher.dispatch(&Event { kind: 0, value: i32::MIN }),
        DispatchReport { invoked: 1, stopped: false }
    );
    assert_eq!(*calls.borrow(), vec![u8::MAX, 0]);
}

#[test]
fn separate_dispatchers_share_no_handlers_or_completion_state() {
    let first_count = Rc::new(RefCell::new(0usize));
    let second_count = Rc::new(RefCell::new(0usize));
    let mut first = Dispatcher::new();
    let mut second = Dispatcher::new();

    let count = Rc::clone(&first_count);
    first.on(1, Box::new(move |_| {
        *count.borrow_mut() += 1;
        HandlerFlow::Stop
    }));

    let count = Rc::clone(&second_count);
    second.on(1, Box::new(move |_| {
        *count.borrow_mut() += 1;
        HandlerFlow::Continue
    }));

    let event = Event { kind: 1, value: 5 };
    assert_eq!(first.dispatch(&event), DispatchReport { invoked: 1, stopped: true });
    assert_eq!(second.dispatch(&event), DispatchReport { invoked: 1, stopped: false });
    assert_eq!(*first_count.borrow(), 1);
    assert_eq!(*second_count.borrow(), 1);
}
