mod solution;

use solution::{EmitReport, ListenerState, SignalHub};
use std::cell::{Cell, RefCell};
use std::rc::Rc;

#[test]
fn stream_without_listeners_reports_zero_counts() {
    let mut hub = SignalHub::new();
    assert_eq!(
        hub.emit(12, b"unused"),
        EmitReport { invoked: 0, completed: 0 }
    );
}

#[test]
fn listeners_run_in_subscription_order_and_receive_the_same_slice() {
    let calls = Rc::new(RefCell::new(Vec::new()));
    let expected_address = Rc::new(Cell::new(0usize));
    let mut hub = SignalHub::new();

    for marker in [1u8, 2, 3] {
        let calls = Rc::clone(&calls);
        let expected_address = Rc::clone(&expected_address);
        hub.subscribe(9, Box::new(move |payload| {
            assert_eq!(payload.as_ptr() as usize, expected_address.get());
            calls.borrow_mut().push((marker, payload.to_vec()));
            ListenerState::Listening
        }));
    }

    let payload = [4u8, 5, 6, 7];
    expected_address.set(payload.as_ptr() as usize);
    assert_eq!(
        hub.emit(9, &payload),
        EmitReport { invoked: 3, completed: 0 }
    );
    assert_eq!(
        *calls.borrow(),
        vec![(1, payload.to_vec()), (2, payload.to_vec()), (3, payload.to_vec())]
    );
}

#[test]
fn completed_listeners_are_removed_without_skipping_following_listeners() {
    let calls = Rc::new(RefCell::new(Vec::new()));
    let mut hub = SignalHub::new();

    let calls_a = Rc::clone(&calls);
    hub.subscribe(3, Box::new(move |_| {
        calls_a.borrow_mut().push('A');
        ListenerState::Complete
    }));

    let calls_b = Rc::clone(&calls);
    hub.subscribe(3, Box::new(move |_| {
        calls_b.borrow_mut().push('B');
        ListenerState::Listening
    }));

    let calls_c = Rc::clone(&calls);
    hub.subscribe(3, Box::new(move |_| {
        calls_c.borrow_mut().push('C');
        ListenerState::Complete
    }));

    assert_eq!(
        hub.emit(3, b"first"),
        EmitReport { invoked: 3, completed: 2 }
    );
    assert_eq!(*calls.borrow(), vec!['A', 'B', 'C']);

    assert_eq!(
        hub.emit(3, b"second"),
